use vstd::prelude::*;

verus! {

fn array_split(a: Vec<i32>) -> (left: Vec<i32>, right: Vec<i32>)
    ensures
        // Length relationship (covers both branches)
        left.len() + right.len() == a.len(),

        // Contents are a partition preserving order: left is prefix, right is suffix
        left@ + right@ == a@,

        // If the input is very small, we return (a, [])
        (a.len() <= 1) ==> (left@ == a@ && right@ == Seq::<i32>::empty()),

        // If the input is larger, we split into two non-empty parts, each strictly shorter
        (a.len() > 1) ==> (
            0 < left.len()
            && 0 < right.len()
            && left.len() < a.len()
            && right.len() < a.len()
        ),
{
    let n = a.len();
    if n <= 1 {
        // For n = 0: returns ([], [])
        // For n = 1: returns ([a[0]], [])
        return (a, Vec::new());
    }

    // Split into two non-empty parts so both are strictly shorter than `a`.
    let mid = n / 2; // with n > 1, mid is in [1, n-1]
    let mut left = a;
    let right = left.split_off(mid); // left keeps [0..mid), right gets [mid..n)
    (left, right)
}

} // verus!

